package leetcode.solutions.easy.binarysearch;

/**
 * Pattern: Binary Search
 * Time complexity: O(log n)
 * Space complexity: O(1)
 * */

public class BinarySearch {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        while (left <= right) {
            int m = (left + right) / 2;

            if (target > nums[m]) {
                left = m + 1;
            } else if (target < nums[m]) {
                right = m - 1;
            } else {
                return m;
            }
        }
        return -1;
    }
}

package leetcode.solutions.easy.bitmanipulation;

/**
 * Pattern: Bit Manipulation
 * Time complexity: O(1)
 * Space complexity: O(k)
 * Intuition: since the specs say that values will be in the range [1, 1000000],
 * we can keep an array with a slot for each value. If we use 32-bit integers, we can save a lot of space
 * compared to using booleans, namely 1000000 / 32 = 31250.
 */

public class DesignHashSet {
    private final int[] set;

    public DesignHashSet() {
        // key is in the range [1, 1000000]
        // 31251 * 32 = 1000032
        set = new int[31251];
    }

    public void add(int key) {
        set[key / 32] |= getMask(key);
    }

    public void remove(int key) {
        if (contains(key)) {
            set[key / 32] ^= getMask(key);
        }
    }


    /**
     * Example:
     * set[2] = ...00110010     → key 70 was never added, bit 6 is 0
     * mask   = ...01000000     → getMask(70)
     * set[2] & mask:
     *   00110010
     * & 01000000
     * ----------
     *   00000000  →  result = 0  → key 70 does not exist
     */
    public boolean contains(int key) {
        return (set[key / 32] & getMask(key)) != 0;
    }

    /**
     * Example:
     * key = 70
     * key / 32 = 2           → int at index 2
     * key % 32 = 6           → bit 6 within that int
     * getMask(70) = 1 << 6   → 01000000
     * set[2] = ...01000000   → bit 6 is ON, meaning key 70 exists
     */
    private int getMask(int key) {
        return 1 << (key % 32);
    }
}

package leetcode.solutions.easy.graphs;

/**
 * Pattern: Graphs
 * Time complexity: O(n * m)
 * Space complexity: O(m * n)
 */

class Solution {
    int ROWS;
    int COLS;
    int color;
    int originalColor;

    public int[][] floodFill(int[][] image, int sr, int sc, int color) {
        this.ROWS = image.length;
        this.COLS = image[0].length;
        this.color = color;
        this.originalColor = image[sr][sc];
        flood(image, sr, sc);
        return image;
    }

    private void flood(int[][] image, int r, int c) {
        if (r < 0 || c < 0 || r == ROWS || c == COLS || image[r][c] != originalColor
                || image[r][c] == color) return;

        image[r][c] = color;

        flood(image, r + 1, c);
        flood(image, r, c + 1);
        flood(image, r - 1, c);
        flood(image, r, c - 1);
    }
}

package leetcode.solutions.easy.greedy;

/**
 * Patter: Greedy (sliding window structurally)
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class BestTimeToBuyAndSellStocks {
    public int maxProfit(int[] prices) {
        int left = 0, maxSoFar = 0;

        for (int right = 0; right < prices.length; right++) {
            if (prices[right] <= prices[left]) left = right;
            else {
                int profit = prices[right] - prices[left];
                maxSoFar = Math.max(maxSoFar, profit);
            }
        }
        return maxSoFar;
    }
}

package leetcode.solutions.easy.hashing;

import java.util.HashSet;
import java.util.Set;

/**
 * Pattern: Hashing
 * Time complexity: O(n)
 * Space complexity: O(n)
 * */

public class ContainsDuplicate {
    public boolean hasDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();

        for (int num : nums) {
            if (seen.contains(num)) return true;
            seen.add(num);
        }

        return false;
    }
}

package leetcode.solutions.easy.hashing;

import java.util.Arrays;

/**
 * Pattern: Hashing
 * Time complexity: O(1) for all the methods
 * Space complexity: O(1000001)
 */

public class DesignHashMap {
    int[] map;

    public DesignHashMap() {
        map = new int[1000001];
        Arrays.fill(map, -1);
    }

    public void put(int key, int value) {
        map[key] = value;
    }

    public int get(int key) {
        if (map[key] != -1) return map[key];
        else return -1;
    }

    public void remove(int key) {
        map[key] = -1;
    }
}

package leetcode.solutions.easy.hashing;

/**
 * Pattern: Hashing
 * Time complexity: O(m + n), where m is the length of s and n is the length of t.
 * Space complexity: O(1) since we have at most 26 different characters.
 * */

public class IsAnagram {
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;

        int[] occurrences = new int[26];
        for (int i = 0; i < s.length(); i++) {
            occurrences[s.charAt(i) - 'a']++;
            occurrences[t.charAt(i) - 'a']--;
        }

        for (int val : occurrences) {
            if (val != 0) return false;
        }
        return true;
    }
}

package leetcode.solutions.easy.hashing;

import java.util.HashMap;
import java.util.Map;

/**
 * Pattern: Hashing
 * Time complexity: O(n) where n is the length of s.
 * Space complexity: O(n)

 * Intuition: we first collect frequencies of characters.
 * If we get an even frequency we can just add it to maxLength as is,
 * if it is odd, we can add frequency - 1 (even). We also have to keep track
 * of the existence of at least one odd frequency (hasOddValues) as this will allow
 * us to add + 1 at the end (center letter of the constructed palindrome).
 */

public class LongestPalindrome {
    public int longestPalindrome(String s) {
        Map<Character, Integer> frequencyMap = new HashMap<>();

        for (char c : s.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        int maxLength = 0;
        boolean hasOddValues = false;
        for (Integer frequency : frequencyMap.values()) {
            if (frequency % 2 == 0) maxLength += frequency;
            else {
                maxLength += frequency - 1;
                hasOddValues = true;
            }
        }
        return hasOddValues ? maxLength + 1 : maxLength;
    }
}

package leetcode.solutions.easy.hashing;

import java.util.HashMap;
import java.util.Map;

/**
 * Pattern: Hashing
 * Time complexity: O(n)
 * Space complexity: O(n)
 * */

public class TwoSum {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> complementToIndex = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int complement = target - num;

            if (complementToIndex.containsKey(complement)) {
                int index = complementToIndex.get(complement);
                return new int[] { index, i };
            }
            complementToIndex.put(num, i);
        }
        return new int[] {};
    }
}

package leetcode.solutions.easy.heaps;

import java.util.PriorityQueue;

/**
 * Pattern: min-heap
 * Time complexity: constructor takes O(n * log k), where n is the number of values in nums
 * add() takes O(log k) time complexity.
 * Space complexity: O(k)
 */

public class KthLargestElementInAStream {
    private final PriorityQueue<Integer> minHeap;
    private final int k;

    public KthLargestElementInAStream(int k, int[] nums) {
        this.k = k;
        this.minHeap = new PriorityQueue<>();

        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k) minHeap.poll();
        }
    }

    public int add(int val) {
        minHeap.offer(val);

        if (minHeap.size() > k) minHeap.poll();

        return minHeap.peek();
    }
}

package leetcode.solutions.easy.heaps;

import java.util.Collections;
import java.util.PriorityQueue;

/**
 * Pattern: max-heap
 * Time complexity: O(n log n)
 * Space complexity: O(n), where n is the number of stones.
 */

public class LastStoneWeight {
    public int lastStoneWeight(int[] stones) {
        PriorityQueue<Integer> maxHeap =
                new PriorityQueue<>(Collections.reverseOrder());

        for (int stone : stones) maxHeap.add(stone);

        while (maxHeap.size() > 1) {
            int x = maxHeap.poll();
            int y = maxHeap.poll();

            // `offer` is more idiomatic for queue than `add`.
            if (x > y) maxHeap.offer(x - y);
        }
        return maxHeap.isEmpty() ? 0 : maxHeap.peek();
    }
}

package leetcode.solutions.easy.intervals;

import leetcode.solutions.types.Interval;

import java.util.List;

/**
 * Pattern: Intervals
 * Time complexity: O(n log n)
 * Space complexity: O(n) due to sorting algorithm.
 */

class MeetingRooms {
    public boolean canAttendMeetings(List<Interval> intervals) {
        intervals.sort((a, b) -> Integer.compare(a.start, b.start));

        for (int i = 0; i < intervals.size() - 1; i++) {
            Interval i1 = intervals.get(i);
            Interval i2 = intervals.get(i + 1);
            if (i2.start < i1.end) return false;
        }
        return true;
    }
}

package leetcode.solutions.easy.linkedlist;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class LinkedListCycle {
    public boolean hasCycle(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;

            if (slow == fast) {
                return true;
            }
        }
        return false;
    }
}

package leetcode.solutions.easy.linkedlist;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List
 */

public class MergeTwoSortedLinkedLists {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode dummyNode = new ListNode(0);
        ListNode mergedList = dummyNode;

        while (list1 != null && list2 != null) {
            if (list1.val < list2.val) {
                // Always assign the new node to the `next` of the current list!
                mergedList.next = list1;
                list1 = list1.next;
            } else {
                mergedList.next = list2;
                list2 = list2.next;
            }
            mergedList = mergedList.next;
        }

        // No need to check that list1 or list2 are null here,
        // as otherwise we would not end up here from the while loop above.
        if (list1 != null) {
            mergedList.next = list1;
        } else if (list2 != null) {
            mergedList.next = list2;
        }

        return dummyNode.next;
    }
}

package leetcode.solutions.easy.linkedlist;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class ReverseLinkedList {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null;
        ListNode curr = head;

        while (curr != null) {
            ListNode tmp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = tmp;
        }
        return prev;
    }
}

package leetcode.solutions.easy.math;

import java.util.HashSet;
import java.util.Set;

/*
 * Pattern: Math (Hashing)
 * Time Complexity: O(log n)
 * Each iteration computes the sum of the squares of n’s digits, which
 * takes O(log n) time. The process quickly converges to a small range,
 * so the number of iterations is constant-bounded.
 *
 * Space Complexity: O(log n)
 * A HashSet stores previously seen values to detect cycles. The number
 * of stored values is bounded by the digit-square sequence size.
 */

public class HappyNumber {
    public boolean isHappy(int n) {
        Set<Integer> seen = new HashSet<>();

        while (!seen.contains(n)) {
            seen.add(n);
            n = sumOfSquares(n);
            if (n == 1) return true;
        }
        return false;
    }

    private int sumOfSquares(int n) {
        int output = 0;

        while (n > 0) {
            int digit = n % 10;
            // Better than Math.pow() as it returns a double and casting would be needed.
            output += digit * digit;
            n /= 10;
        }
        return output;
    }
}

package leetcode.solutions.easy.stack;

import java.util.Stack;

/**
 * Pattern: Stack
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class ValidParentheses {
    public boolean isValid(String s) {
        Stack<Character> stack = new Stack<>();

        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else if (!stack.isEmpty() && c == ')' && stack.peek() == '(') {
                stack.pop();
            } else if (!stack.isEmpty() && c == ']' && stack.peek() == '[') {
                stack.pop();
            } else if (!stack.isEmpty() && c == '}' && stack.peek() == '{') {
                stack.pop();
            } else {
                return false;
            }
        }
        return stack.isEmpty();
    }
}

package leetcode.solutions.easy.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Trees
 * Time complexity: O(n)
 * Space complexity: O(n)
 * Note: our recursive function returns [isBalanced = [0, 1], depth of tree rooted at that node]
 * We could use a global isBalanced variable instead, but it is cleaner to have no sahred state
 * between recursive calls and have everything in boolean[] balanced.
 */

public class BalancedBinaryTree {
    public boolean isBalanced(TreeNode root) {
        return dfs(root)[0] == 1;
    }

    private int[] dfs(TreeNode root) {
        if (root == null) return new int[]{1, 0};

        int[] left = dfs(root.left);
        int[] right = dfs(root.right);

        boolean balanced = ((left[0] == 1) && (right[0] == 1)) && Math.abs(left[1] - right[1]) <= 1;
        return new int[]{balanced ? 1 : 0, 1 + Math.max(left[1], right[1])};
    }
}

package leetcode.solutions.easy.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Trees
 * Time complexity: O(n)
 * Space complexity: O(n)
 * Note: we need a local max variable because of an edge case: when the diameter is not obtainable by
 * connecting the left diameter with the right diameter through the root node, i.e. when the diameter is entirely
 * contained and "isolated" in one of the two root subtrees.
 * To understand this solution, a drawing will be quite helpful.
 */

public class DiameterOfBinaryTree {
    public int diameterOfBinaryTree(TreeNode root) {
        // We use int[] because we need a mutable reference as "current max" variable.
        // There are other possibilities but int[] is lightweight and idiomatic for coding interviews.
        int[] diameter = new int[1];
        dfs(root, diameter);
        return diameter[0];
    }

    private int dfs(TreeNode root, int[] diameter) {
        if (root == null) return 0;

        int left = dfs(root.left, diameter);
        int right = dfs(root.right, diameter);
        diameter[0] = Math.max(diameter[0], left + right);
        // We return the maximum value because we need to pick: we cannot
        // go up in the three by taking the sum of both subtrees.
        return 1 + Math.max(left, right);
    }
}

package leetcode.solutions.easy.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Tree (DFS)
 * Time complexity: O(n)
 * Space complexity: O(n) for recursion stack.
 */

public class InvertBinaryTree {
    public TreeNode invertTree(TreeNode root) {
        if (root == null) return null;

        TreeNode tmp = root.left;
        root.left = root.right;
        root.right = tmp;
        root.left = this.invertTree(root.left);
        root.right = this.invertTree(root.right);
        return root;
    }
}

package leetcode.solutions.easy.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Tree (DFS)
 * Time complexity: O(n)
 * Space complexity: O(n), due to recursion stack.
 */

public class MaximumDepthOfBinaryTree {
    public int maxDepth(TreeNode root) {
        if (root == null) return 0;
        return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
    }
}

package leetcode.solutions.easy.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Trees
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class SameTree {
    public boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;
        if (p == null || q == null) return false;

        return p.val == q.val && isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}

package leetcode.solutions.easy.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Trees
 * Time complexity: O(n * m), where n is the size of root and m is the size of subRoot.
 * Space complexity: O(n)
 */

public class SubtreeOfAnotherTree {
    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        if (root == null && subRoot == null) return true;
        if (root == null) return false;

        return isSameTree(root, subRoot) || isSubtree(root.left, subRoot) || isSubtree(root.right, subRoot);
    }

    private boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;
        if (p == null || q == null) return false;

        return p.val == q.val && isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}

package leetcode.solutions.easy.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(m + n)
 * Space complexity: O(m + n)
 */

public class MergeStringAlternately {
    public String mergeAlternately(String word1, String word2) {
        // Use StringBuilder for better memory usage.
        StringBuilder res = new StringBuilder();
        int i = 0, j = 0;

        while (i < word1.length() && j < word2.length()) {
            res.append(word1.charAt(i++));
            res.append(word2.charAt(j++));
        }

        // Here we do not risk indexOutOfBounds because substring() does not
        // throw if index == word.length, unlike e.g. charAt().
        res.append(word1.substring(i));
        res.append(word2.substring(j));
        return res.toString();
    }
}

package leetcode.solutions.easy.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(n)
 * Space complexity: O(1), as the array is modified in place.
 * Intuition: we "move" occurrences of val to the end of the array in this way:
 * if we read a value that is not val, we write it, else we keep write where it is, and we advance with read only.
 * Advancing write *only* when a swap happens also allows us to keep it fixed on an occurrence of val when we find it.
 */

public class RemoveElement {
    public int removeElement(int[] nums, int val) {
        int write = 0;

        for (int read = 0; read < nums.length; read++) {
            if (nums[read] != val) {
                nums[write] = nums[read];
                write++;
            }
        }
        return write;
    }
}

package leetcode.solutions.easy.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(n)
 * Space complexity: O(1)
 * Intuition:
 * A clever observation: rotating an array by k is equivalent to moving the last k elements to the front.
 * We can achieve this with three reversals. First, reverse the entire array. Now the last k elements are at the front, but in reverse order.
 * Reverse the first k elements to fix their order. Finally, reverse the remaining elements to restore their original order.
 */

public class RotateArray {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        // as k could be larger than n.
        k %= n;

        reverse(nums, 0, n - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, n - 1);
    }

    private void reverse(int[] nums, int l, int r) {
        while (l < r) {
            int tmp = nums[l];
            nums[l] = nums[r];
            nums[r] = tmp;
            l++;
            r--;
        }
    }
}

package leetcode.solutions.easy.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(n)
 * Space complexity: O(1)
 * */

public class ValidPalindrome {
    public boolean isPalindrome(String s) {
        int l = 0, r = s.length() - 1;

        while (l < r) {
            while (l < r && !isAlphaNum(s.charAt(l))) l++;
            while (r > l && !isAlphaNum(s.charAt(r))) r--;

            // The problem statement expects us to compare only lowercase characters.
            if (Character.toLowerCase(s.charAt(l)) != Character.toLowerCase(s.charAt(r))) {
                return false;
            }
            // Do not forget to move pointers here too.
            l++; r--;
        }
        return true;
    }

    private boolean isAlphaNum(char c) {
        return (c >= 'A' && c <= 'Z' ||
                c >= 'a' && c <= 'z' ||
                c >= '0' && c <= '9');
    }

    // Above method could also be
    // private boolean isAlphaNum(char c) {
    //  return isLetter(c) || isDigit(c);
    // }
}

package leetcode.solutions.easy.twopointers;

/**
 * Time complexity: O(n)
 * Space complexity: O(1)
 * Intuition: if we find a mismatch, try skipping the left value and the right value.
 * If any of the two return true, then return true, else return false.
 */

public class ValidPalindromeII {
    public boolean validPalindrome(String s) {
        int left = 0, right = s.length() - 1;

        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return isPalindrome(s, left + 1, right) || isPalindrome(s, left, right - 1);
            }
            left++;
            right--;
        }
        return true;
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }
}

package leetcode.solutions.easy.various;

/**
 * Pattern: Vertical Scanning (Iteration)
 * Time complexity: O(n * m), where n is the number of strings and m is the average length of these strings.
 * Space complexity: O(1), since we did not use extra space.
 * Intuition: compare character at index i for each string.
 * As soon as a mismatch is found, return prefix without last character, i.e. strs[0].substring(0, index)
 */

public class LongestCommonPrefix {
    public String longestCommonPrefix(String[] strs) {
        int index = 0;

        while (true) {
            if (index >= strs[0].length()) return strs[0].substring(0, index);

            char curr = strs[0].charAt(index);

            for (String s : strs) {
                if (index >= s.length() || s.charAt(index) != curr) {
                    return strs[0].substring(0, index);
                }
            }
            index++;
        }
    }
}

package leetcode.solutions.easy.various;

/**
 * Pattern: Boyer-Moore Voting Algorithm
 * Time complexity: O(n)
 * Space complexity: O(1)
 * Intuition:  The majority element (appearing > n/2 times) will always "survive" a cancellation battle against all other elements combined.
 * Think of it like a vote war:
 * - Every element "votes" for itself
 * - When two different elements meet, they cancel each other out
 */

public class MajorityElement {
    public int majorityElement(int[] nums) {
        int res = 0, count = 0;

        for (int num : nums) {
            if (count == 0) {
                res = num;
            }
            count += (num == res) ? 1 : -1;
        }
        return res;
    }
}

package leetcode.solutions.easy.various;

/**
 * Pattern: Prefix Sum
 * Time complexity: constructor takes O(n), while sumRange() takes O(1)
 * Space complexity: O(n)
 */

public class RangeSumQueryImmutable {
    private int[] prefix;

    public RangeSumQueryImmutable(int[] nums) {
        // We want first value of prefix to be 0, so we set nums.length + 1
        // This is needed for later, to facilitate calculations.
        prefix = new int[nums.length + 1];

        for (int i = 0; i < nums.length; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
    }

    public int sumRange(int left, int right) {
        return prefix[right + 1] - prefix[left];
    }
}

package leetcode.solutions.hard.linkedlists;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List
 * Time complexity: O(n * k), where n is the average length of the lists and k is the number of lists.
 * Space complexity: O(1)
 */

public class MergeKSortedLinkedLists {
    public ListNode mergeKLists(ListNode[] lists) {
        ListNode dummy = new ListNode(0);
        ListNode curr = dummy;

        while (true) {
            int minNodeIndex = -1;
            for (int i = 0; i < lists.length; i++) {
                if (lists[i] == null) {
                    continue;
                }

                if (minNodeIndex == -1 || lists[i].val < lists[minNodeIndex].val) {
                    minNodeIndex = i;
                }
            }

            // Break because all linked lists are empty or we reached the end of all linked lists.
            if (minNodeIndex == -1) {
                break;
            }

            // We reuse the already existing nodes.
            curr.next = lists[minNodeIndex];
            lists[minNodeIndex] = lists[minNodeIndex].next;
            curr = curr.next;
        }
        return dummy.next;
    }
}

package leetcode.solutions.hard.slidingwindow;

import java.util.HashMap;
import java.util.Map;

/**
 * Pattern: Sliding Window
 * Time complexity: O(n + m)
 * Space complexity: O(n + m), but practically, since alphabet is bounded (ASCII or Unicode subset), O(1).
 */

public class MinimumWindowSubstring {
    public String minWindow(String s, String t) {
        if (s.length() < t.length() || t.isEmpty()) return "";

        // Count frequencies of characters in t.
        Map<Character, Integer> countT = new HashMap<>();
        for (int i = 0; i < t.length(); i++) {
            countT.put(t.charAt(i), 1 + countT.getOrDefault(t.charAt(i), 0));
        }

        int have = 0, minSoFar = Integer.MAX_VALUE, need = countT.size();
        Map<Character, Integer> window = new HashMap<>();
        int[] res = { -1, -1 };
        int l = 0;

        for (int r = 0; r < s.length(); r++) {
            char characterS = s.charAt(r);
            window.put(characterS, 1 + window.getOrDefault(characterS, 0));

            // `have` means that our window contains a character occurring in t and with the same frequency.
            if (countT.containsKey(characterS) && countT.get(characterS).equals(window.get(characterS))) {
                have++;
            }

            // While have == need, we can remove on the left and potentially find a smaller window.
            // If we start lacking something in the window, we leave the while loop and increase r, continuing the search.
            while (have == need) {
                if ((r - l + 1) < minSoFar) {
                    minSoFar = (r - l + 1);
                    res[0] = l;
                    res[1] = r;
                }

                // Do all the updates that follow l++.
                char leftChar = s.charAt(l);
                window.put(leftChar, window.get(leftChar) - 1);
                if (countT.containsKey(leftChar) && window.get(leftChar) < countT.get(leftChar)) {
                    have--;
                }
                l++;
            }
        }

        // We need res[1] + 1 as .substring() is exclusive on the right.
        return minSoFar == Integer.MAX_VALUE ? "" : s.substring(res[0], res[1] + 1);
    }
}

package leetcode.solutions.hard.stack;

import java.util.Stack;

/**
 * Pattern: Stack
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class LargestRectangleInHistogram {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        Stack<Integer> stack = new Stack<>();
        // Left and right boundaries: until which index can we "extend" a bar to the left and to the right?
        int[] left = new int[n];
        int[] right = new int[n];

        // Find the left boundaries
        for (int i = 0; i < n; i++) {
            left[i] = -1;
            while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
                stack.pop();
            }

            if (!stack.isEmpty()) {
                left[i] = stack.peek();
            }
            stack.push(i);
        }

        stack.clear();

        // Find the right boundaries
        for (int i = n - 1; i >= 0; i--) {
            right[i] = n;
            while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                right[i] = stack.peek();
            }
            stack.push(i);
        }

        int largestArea = 0;
        for (int i = 0; i < n; i++) {
            // left[i] and right[i] are exclusive boundaries (the first shorter bar on each side),
            // so the width is the count of indices strictly between them: right[i] - left[i] - 1
            largestArea = Math.max(largestArea, heights[i] * (right[i] - left[i] - 1));
        }
        return largestArea;
    }
}

package leetcode.solutions.hard.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class TrappingRainWater {
    public int trap(int[] height) {
        int maxLeft = 0, maxRight = 0;
        int l = 0, res = 0, r = height.length - 1;

        while (l < r) {
            if (maxLeft > height[l] && maxRight > height[l]) {
                res += Math.min(maxLeft, maxRight) - height[l];
            } else if (maxLeft > height[r] && maxRight > height[r]) {
                res += Math.min(maxLeft, maxRight) - height[r];
            }

            maxLeft = Math.max(maxLeft, height[l]);
            maxRight = Math.max(maxRight, height[r]);

            if (height[l] < height[r]) l++;
            else {
                r--;
            }
        }
        return res;
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(2^(t/m)), where 2 comes from the two choices we have at each step (pick/take).
 * Space complexity: O(t/m)
 * Where t is the given target and m is the minimum value in nums.
 */

public class CombinationSum {
    public List<List<Integer>> combinationSum(int[] nums, int target) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(nums, 0, target, 0, new ArrayList<>(), res);
        return res;
    }

    /**
     * Note: we pass sum instead of a combination list, as otherwise we would need to
     * calculate the sum of the combination every time and this is not efficient.
     */
    private void dfs(int[] nums, int i, int target, int sum,
                     List<Integer> combination, List<List<Integer>> res) {

        if (sum == target) {
            res.add(new ArrayList<>(combination));
            return;
        }

        if (i == nums.length || sum > target) return;

        // Option 1: skip nums[i].
        dfs(nums, i + 1, target, sum, combination, res);

        // Option 2: take nums[i].
        // Option 3: "take nums[i] only once" is obtained by means of the other two: take first time and then skip.
        combination.add(nums[i]);
        dfs(nums, i, target, sum + nums[i], combination, res);
        combination.removeLast(); // backtrack.
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(n * 2^n), as there are up to 2^n subsets and for each of them we can take a copy in O(n).
 * Space complexity: O(n) for the recursion depth.

 * Example: candidates sorted → [1,2,2,4,5,6,9], target = 8.
 * The combination [2,6] should appear once even though there are two 2's.
 * We include the first 2 → explore → find [2,6].
 * After backtracking, we return to the same depth and skip the second 2,
 * otherwise we will get a duplicate. Note: why skipping duplicates before and not
 * after going in the 'skip' branch on line 46? Because if we go in the 'skip' branch
 * when we return at the same depth of the first 2, then there is a combination where we take
 * the second 2 and 6 again, which leads to a duplicate. We want to skip duplicates first and then
 * go to the skip branch.
 */

public class CombinationSumII {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        List<List<Integer>> res = new ArrayList<>();
        List<Integer> combination = new ArrayList<>();
        Arrays.sort(candidates);

        dfs(candidates, 0, target, 0, combination, res);
        return res;
    }

    private void dfs(int[] candidates, int i, int target, int sum,
                     List<Integer> combination, List<List<Integer>> res) {
        if (sum == target) {
            res.add(new ArrayList<>(combination));
            return;
        }

        if (i >= candidates.length || sum > target) return;

        combination.add(candidates[i]);
        dfs(candidates, i + 1, target, sum + candidates[i], combination, res);
        combination.removeLast();

        // This is the same idea used in ThreeSum.
        while (i < candidates.length - 1 && candidates[i] == candidates[i + 1]) i++;

        dfs(candidates, i + 1, target, sum, combination, res);
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Backtracking (DFS)

 * Time complexity: O(4^n / sqrt(n))
 * Explanation: we generate all sequences of length 2n and their number is the n-th Catalan number.
 * O(4^n / sqrt(n)) is the result of multiplying the Catalan number by n, which we need to do because,
 * in the base case, we add our combination to the final list, which takes O(n).
 * Note: our string management technically takes more than O(n) (O(n^2)) as we are creating a brand-new string every time
 * we recursively call dfs().

 * Space complexity: O(n), for the recursion stack.

 * Note: since we are using String data type, which is immutable, we do not need to do manual state management.
 * Every time we write, e.g., string + '(', a new string gets created in memory.
 * Possible interview follow-up: how would you make this more memory-efficient? By using StringBuilder, which is mutable.
 * This of course will imply that we need to do more state management, in particular by popping: sb.deleteCharAt(sb.length() - 1);
 */	

public class GenerateParentheses {
    List<String> res = new ArrayList<>();
    public List<String> generateParenthesis(int n) {
        dfs(n, "", 0, 0);
        return res;
    }

    private void dfs(int n, String string, int numberOpen, int numberClosed) {
        // When string is balanced, and we reached n, string is a valid combination.
        // This is true only if we respected below rules though, because, e.g.
        // ")))(((" would pass this base case for n = 3.
        if (n == numberOpen && numberOpen == numberClosed) {
            res.add(string);
            return;
        }

        // By default, insert '(' if possible.
        if (numberOpen < n) {
            dfs(n, string + '(', numberOpen + 1, numberClosed);
        }

        // Insert ')' as long as our combination does not become unbalanced.
        if (numberClosed + 1 <= numberOpen) {
            dfs(n, string + ')', numberOpen, numberClosed + 1);
        }
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(n * 4ⁿ), where n comes from combination.toString() and 4ⁿ
 * from the fact that we have 4 letters per digit in the worst case.
 * Space complexity: O(n)
 */

public class LetterCombinationsOfAPhoneNumber {
    // Using char[] instead of List<Character> avoids boxing, reduces memory use,
    // and iterates faster. Lists store Character objects (heap + indirection),
    // while char[] is primitive, compact, and ideal for high‑performance backtracking.
    private static final Map<Character, char[]> KEYPAD = Map.of(
            '2', new char[]{'a','b','c'},
            '3', new char[]{'d','e','f'},
            '4', new char[]{'g','h','i'},
            '5', new char[]{'j','k','l'},
            '6', new char[]{'m','n','o'},
            '7', new char[]{'p','q','r','s'},
            '8', new char[]{'t','u','v'},
            '9', new char[]{'w','x','y','z'}
    );

    private final List<String> res = new ArrayList<>();

    public List<String> letterCombinations(String digits) {
        if (digits.isEmpty()) return res;
        // StringBuilder is the mutable version of String.
        // We use StringBuilder instead of String for the huge performance boost it gives in backtracking.
        backtracking(0, digits, new StringBuilder());
        return res;
    }

    private void backtracking(int i, String digits, StringBuilder combination) {
        if (i == digits.length()) {
            res.add(combination.toString());
            return;
        }

        char[] characters = KEYPAD.get(digits.charAt(i));
        for (char character : characters) {
            combination.append(character);
            backtracking(i + 1, digits, combination);
            combination.deleteCharAt(combination.length() - 1);
        }
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(n * n!), as we generate every possible permutation (n!) and we copy it (n).
 * Space complexity: O(n), for the recursion depth and the `pick` list we keep throughout the algorithm.
 */

public class Permutations {
    List<List<Integer>> res = new ArrayList<>();

    public List<List<Integer>> permute(int[] nums) {
        dfs(nums, new ArrayList<>(), new boolean[nums.length]);
        return res;
    }

    /** `pick` array tells us which elements we already picked in the current combination. */
    private void dfs(int[] nums, List<Integer> permutation, boolean[] pick) {
        if (permutation.size() == nums.length) {
            res.add(new ArrayList<>(permutation));
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (!pick[i]) {
                pick[i] = true;
                permutation.add(nums[i]);
                dfs(nums, permutation, pick);
                // backtrack.
                permutation.removeLast();
                pick[i] = false;
            }
        }
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(n * 2^n), as there are two choices per element and each copy costs O(n).
 * Space complexity: O(n), for max recursion depth. This does not consider output list.
 */

public class Subsets {
    public List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> res = new ArrayList<>();
        List<Integer> subset = new ArrayList<>();
        dfs(nums, 0, subset, res);
        return res;
    }

    private void dfs(int[] nums, int i, List<Integer> subset, List<List<Integer>> res) {
        if (i == nums.length) {
            // new ArrayList<>(subset) creates a "shallow copy" of subset, which means that elements are not copied, but the list itself is.
            // The reason why we need a copy is that ArrayList is a reference type, and as such its reference
            // would still be accessible in other recursive calls (e.g. when we pop from it), but we do not want that.
            res.add(new ArrayList<>(subset));
            return;
        }

        dfs(nums, i + 1, subset, res);
        subset.add(nums[i]);
        dfs(nums, i + 1, subset, res);
        subset.removeLast();
    }
}

package leetcode.solutions.medium.backtracking;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(n * 2^n), as there are two choices per element and each copy costs O(n).
 * Space complexity: O(n), for max recursion depth.
 */

public class SubsetsII {
    List<List<Integer>> res = new ArrayList<>();
    public List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        dfs(nums, 0, new ArrayList<>());
        return res;
    }

    private void dfs(int[] nums, int i, List<Integer> subset) {
        if (i == nums.length) {
            res.add(new ArrayList<>(subset));
            return;
        }

        subset.add(nums[i]);
        dfs(nums, i + 1, subset);
        subset.removeLast();

        // Same idea as Combination Sum II and Three Sum.
        while (i + 1 < nums.length && nums[i] == nums[i + 1]) i++;

        dfs(nums, i + 1, subset);
    }
}

package leetcode.solutions.medium.backtracking;

/**
 * Pattern: Backtracking (DFS)
 * Time complexity: O(m * 4^n), where m is the number of cells and n is the length of word.
 * Space complexity: O(n), for the recursion stack.
 */

public class WordSearch {
    private int ROWS, COLS;

    public boolean exist(char[][] board, String word) {
        ROWS = board.length;
        COLS = board[0].length;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                // We first check if the first character matches. This saves some time on large boards.
                if (board[r][c] == word.charAt(0) && backtrack(board, r, c, word, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean backtrack(char[][] board, int r, int c, String word, int i) {
        if (i == word.length()) return true;

        if (r < 0 || c < 0 || r == ROWS || c == COLS ||
                board[r][c] == '#' || board[r][c] != word.charAt(i)) {
            return false;
        }

        char temp = board[r][c];
        // Remember: always modify grid in place when possible, instead of
        // using a set to keep track of visited cells, as it is more memory-efficient.
        board[r][c] = '#';

        boolean res =
                backtrack(board, r + 1, c, word, i + 1) ||
                        backtrack(board, r - 1, c, word, i + 1) ||
                        backtrack(board, r, c + 1, word, i + 1) ||
                        backtrack(board, r, c - 1, word, i + 1);

        board[r][c] = temp; // restore original char.
        return res;
    }
}

package leetcode.solutions.medium.binarysearch;

/**
 * Pattern: Binary Search
 * Time complexity: O(log n)
 * Space complexity: O(1)
 */

public class FindMinimumInRotatedSortedArray {
    public int findMin(int[] nums) {
        // If array is already sorted, return first value.
        if (nums[0] < nums[nums.length - 1]) return nums[0];

        int left = 0, right = nums.length - 1;
        // If left == right, we found the minimum value.
        while (left < right) {
            int m = (left + right) / 2;

            // we are on the right side.
            if (nums[m] < nums[right]) {
                right = m;
            } else if (nums[m] > nums[right]) { // we are on the left side.
                left = m + 1;
            }
        }
        // right would also do.
        return nums[left];
    }
}

package leetcode.solutions.medium.binarysearch;

import java.util.Arrays;

/**
 * Pattern: Binary Search
 * Time complexity: O(n * log m),
 * where m is the tallest pile and n is the number of elements in piles.
 * Space complexity: O(1)
 */

public class KokoEatingBananas {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;

        // Math.min only works on two primitive values.
        int right = Arrays.stream(piles).max().getAsInt();
        int res = right;

        while (left <= right) {
            int rate = (left + right) / 2;

            int hoursRequired = getHoursRequired(piles, rate);

            if (hoursRequired > h) {
                left = rate + 1;
            } else {
                right = rate - 1;
                res = Math.min(res, rate);
            }
        }
        return res;
    }

    private static int getHoursRequired(int[] piles, int rate) {
        int hoursRequired = 0;
        for (int pile : piles) {
            // We cast pile to double so the division keeps its decimal part; otherwise int division
            // would truncate the result (e.g., 7/3 becomes 2 instead of 2.333...). Math.ceil() needs
            // the decimal value to know whether to round up. After ceil() gives a whole-number hour
            // as a double (e.g., 3.0), we cast it back to int because hoursRequired stores integers.
            hoursRequired += (int) Math.ceil((double) pile / rate);
        }
        return hoursRequired;
    }
}

package leetcode.solutions.medium.binarysearch;

/**
 * Pattern: Binary Search
 * Time complexity: O(log(m * n))
 * Space complexity: O(1)
 * */

public class SearchA2DMatrix {
    public boolean searchMatrix(int[][] matrix, int target) {
        int indexToSearch = -1;

        // Find subarray where target *may* be.
        for (int i = 0; i < matrix.length; i++) {
            int[] subarray = matrix[i];
            if (subarray[0] <= target && target <= subarray[subarray.length - 1]) {
                indexToSearch = i;
            }
        }

        if (indexToSearch == -1) return false;

        // If that subarray exists, binary search it.
        int left = 0, right = matrix[indexToSearch].length - 1;
        while (left <= right) {
            int m = (left + right) / 2;

            if (target > matrix[indexToSearch][m]) {
                left = m + 1;
            } else if (target < matrix[indexToSearch][m]) {
                right = m - 1;
            } else {
                return true;
            }
        }
        return false;
    }
}

package leetcode.solutions.medium.binarysearch;

/**
 * Pattern: Binary Search
 * Time complexity: O(log n), the worst case is if the array is not actually rotated.
 * Space complexity: O(1)
 */

public class SearchInRotatedSortedArray {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        // Same idea as in "Find minimum in rotated sorted array".
        while (left < right) {
            int m = (left + right) / 2;

            // We are on the left side.
            if (nums[m] > nums[right]) {
                left = m + 1;
            } else {
                right = m;
            }
        }

        int pivot = left;
        left = 0;
        right = nums.length - 1;

        // Given the pivot, identify on which side the target *may* be.
        // Then, since each side is sorted, we can binary search it.
        if (target >= nums[pivot] && target <= nums[right]) {
            left = pivot;
        } else {
            right = pivot - 1;
        }

        while (left <= right) {
            int m = (left + right) / 2;

            if (target > nums[m]) {
                left = m + 1;
            } else if (target < nums[m]) {
                right = m - 1;
            } else {
                return m;
            }
        }
        return -1;
    }
}

package leetcode.solutions.medium.binarysearch;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pattern: Binary Search
 * Time complexity: O(1) for set() and O(log n) for get().
 * Space complexity: O(n)
 */

record EntryPair(String name, int timestamp) {}

public class TimeBasedKeyValueStore {
    Map<String, List<EntryPair>> map;

    public TimeBasedKeyValueStore() {
        this.map = new HashMap<>();
    }

    public void set(String key, String value, int timestamp) {
        this.map.computeIfAbsent(key, k -> new ArrayList<>()).add(
                new EntryPair(value, timestamp)
        );
    }

    public String get(String key, int timestamp) {
        if (!this.map.containsKey(key)) return "";

        List<EntryPair> list = this.map.get(key);
        int left = 0, right = list.size() - 1;
        String res = ""; // Use a variable to track the "closest" valid name

        while (left <= right) {
            int middle = left + (right - left) / 2; // Prevents potential overflow

            if (list.get(middle).timestamp() <= timestamp) {
                res = list.get(middle).name();
                left = middle + 1;
            } else {
                right = middle - 1; // Too big, look left
            }
        }
        return res;
    }
}

package leetcode.solutions.medium.graphs;

import leetcode.solutions.types.GraphNode;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pattern: Graphs (DFS)
 * Time complexity: O(V + E)
 * Space complexity: O(V), as we store vertices in a hash map.
 * Note: this algorithm creates a `deep copy` of the original graph: all nodes and edges
 * are recreated at different memory locations.
 */

public class CloneGraph {
    Map<GraphNode, GraphNode> oldToNew;
    public GraphNode cloneGraph(GraphNode node) {
	    // This hash map contains pairs of <reference to old node, reference to copy>.
        oldToNew = new HashMap<>();

        // This allows us to avoid a null check in dfs().
	    // If node is null, simply return null in the base case.
        oldToNew.put(null, null);

        dfs(node);
	    // By default, we return the starting node.
        return oldToNew.get(node);
    }

    private GraphNode dfs(GraphNode node) {
	    // With this base we do not get stuck in loops:
	    // If something has been already `seen`, we find it here.
        if (oldToNew.containsKey(node)) {
            return oldToNew.get(node);
        }

        GraphNode clone = new GraphNode(node.val);
        oldToNew.put(node, clone);
        List<GraphNode> neighbors = node.neighbors;
        for (GraphNode n : neighbors) {
            clone.neighbors.add(dfs(n));
        }
        return clone;
    }
}

package leetcode.solutions.medium.graphs;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * Pattern: Graphs (Topological Sort, Kahn's algorithm)
 * Time complexity: O(V + E)
 * Space complexity: O(V + E)
 */

public class CourseSchedule {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
	    // Add an array for each course/node in the graph.
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) {
            adj.add(new ArrayList<>());
        }

	    // For each node, store in graph the nodes I can reach from there,
	    // and keep track of indegrees.
        int[] indegree = new int[numCourses];
        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);
            indegree[p[0]]++;
        }

	    // Add indegree-0 nodes to queue.
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) {
                queue.add(i);
            }
        }

        int processed = 0;
        while (!queue.isEmpty()) {
            int course = queue.poll();
            processed++;

	        // Check all `next` nodes from course and decrement its indegree.
            for (int next : adj.get(course)) {
                indegree[next]--;
                if (indegree[next] == 0) {
                    queue.add(next);
                }
            }
        }

	    // If we could process all the nodes in the graph, the graph has no cycles,
	    // hence we can take all the courses.
        return processed == numCourses;
    }
}

package leetcode.solutions.medium.graphs;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * Pattern: Graphs (Topological Sort, Kahn's algorithm)
 * Time complexity: O(V + E)
 * Space complexity: O(V + E)
 */

public class CourseScheduleII {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        int[] indegrees = new int[numCourses];
        for (int i = 0; i < numCourses; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);
            indegrees[p[0]]++;
        }

        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegrees[i] == 0) queue.add(i);
        }

        int[] res = new int[numCourses];
        int i = 0;
        while (!queue.isEmpty()) {
            int course = queue.poll();
            res[i] = course;
            i++;
            List<Integer> neighbors = adj.get(course);
            for (Integer next : neighbors) {
                indegrees[next]--;
                if (indegrees[next] == 0) queue.add(next);
            }
        }
        // If we were able to add all the courses, return the path, otherwise empty array.
        return i == numCourses ? res : new int[]{};
    }
}

package leetcode.solutions.medium.graphs;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Pattern: Graphs (Multisource BFS)
 * Time complexity: O(m * n)
 * Space complexity: O(m * n)
 * Intuition: We apply multisource BFS in the following way:
 * - start from treasure locations and explore adjacent land from there.
 * - for example, at treasure (r, c) we check adjacent cells and add the non-visited land cells to the queue,
     marking them as `1` as that is the shortest path.
   - we then continue with the next element in the queue: if it is a treasure, we do the same as before,
     otherwise we continue with a land cell.
   - there is no danger that we explore already visited cells as we only add untouched land cells to the queue
     (i.e. where value = Integer.MAX_VALUE).
 */

public class IslandsAndTreasure {
    public void islandsAndTreasure(int[][] grid) {
        int ROWS = grid.length;
        int COLS = grid[0].length;
        Deque<int[]> queue = new ArrayDeque<>();

	    // Add all treasure locations to the queue.
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (grid[r][c] == 0) {
                    queue.add(new int[]{ r, c });
                }
            }
        }

        int[][] directions = new int[][]{new int[]{1, 0}, new int[]{0, 1}, new int[]{-1, 0}, new int[]{0, -1}};
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int currentRow = cell[0];
            int currentCol = cell[1];

            for (int[] dir : directions) {
                int newRow = currentRow + dir[0];
                int newCol = currentCol + dir[1];

                // Continue if next cell is outside of grid or is not land (Integer.MAX_VALUE).
                // This is what we do NOT want to add to the queue:
		        // - water
		        // - treasures
		        // - land whose value is less than Integer.MAX_VALUE (these were already visited before).
                if (newRow < 0 || newCol < 0 || newRow == ROWS || newCol == COLS || grid[newRow][newCol] != Integer.MAX_VALUE) {
                    continue;
                }

                // So we are dealing with land on the next cell.
                // Update that cell with the value of the current cell + 1. e.g. if current cell is a treasure, next land cell
                // will be 0 + 1 = 1, which is what we expect.
		        // This is better state management than keeping a counter.
                grid[newRow][newCol] = grid[currentRow][currentCol] + 1;
		        // Add next cell to queue.
                queue.add(new int[]{ newRow, newCol });
            }
        }
    }
}

package leetcode.solutions.medium.graphs;

/**
 * Pattern: Graphs (DFS)
 * Time complexity: O(m * n)
 * Space complexity: O(m * n), for the recursion stack.
 */

public class MaxAreaOfIsland {
    private int ROWS;
    private int COLS;

    public int maxAreaOfIsland(int[][] grid) {
        ROWS = grid.length;
        COLS = grid[0].length;
        int maxArea = 0;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (grid[r][c] == 1) {
                    maxArea = Math.max(maxArea, dfs(grid, r, c, 0));
                }
            }
        }
        return maxArea;
    }

    private int dfs(int[][] grid, int r, int c, int area) {
        if (r < 0 || c < 0 || r == ROWS || c == COLS || grid[r][c] == 0) {
            return 0;
        }

        grid[r][c] = 0;
        return 1 + dfs(grid, r + 1, c, area + 1) +
                dfs(grid, r, c + 1, area + 1) +
                dfs(grid, r - 1, c, area + 1) +
                dfs(grid, r, c - 1, area + 1);
    }
}

package leetcode.solutions.medium.graphs;

/**
 * Pattern: Graphs (Disjoint Set Union)
 * Time complexity: O(V + E * α(n)) = O(V + E) in practice, where α is the inverse Ackermann function
 *     - Initialization: O(V) to create parents and size arrays in DSU constructor.
 *     - Processing edges: O(E * α(n)) - iterate through E edges, each union does 2 finds
 *     - With path compression (in find) + union by size (in union), each find is O(α(n)) amortized
 *     - α(n) ≤ 5 for all practical values of n, so effectively O(V + E) in practice
 * Space complexity: O(V)
 * Intuition: every time we can successfully unify two nodes, we know we have one connected component
 * less than before.
 */

class DisjointSetUnion {
    int components;
    int[] parents;
    int[] sizes;

    public DisjointSetUnion(int n) {
        components = n;
        parents = new int[n];
        sizes = new int[n];

        for (int i = 0; i < n; i++) {
            parents[i] = i;
            sizes[i] = 1;
        }
    }

    public int find(int node) {
        if (node != parents[node]) {
            parents[node] = find(parents[node]);
        }
        return parents[node];
    }

    public void union(int v, int u) {
        int pv = find(v);
        int pu = find(u);

        // We return here because, in this case, v and u
        // are already in the same connected component.
        if (pv == pu) return;

        if (sizes[pu] < sizes[pv]) {
            parents[pu] = pv;
            sizes[pv] += sizes[pu];
        } else {
            parents[pv] = pu;
            sizes[pu] += sizes[pv];
        }
        this.components--;
    }

    public int getComponents() {
        return this.components;
    }
}

public class NumberOfConnectedComponentsInUndirectedGraph {
    public int countComponents(int n, int[][] edges) {
        DisjointSetUnion dsu = new DisjointSetUnion(n);

        for (int[] edge : edges) {
            dsu.union(edge[0], edge[1]);
        }
        return dsu.getComponents();
    }
}

package leetcode.solutions.medium.graphs;

/**
 * Pattern: Graphs (DFS)
 * Time complexity: O(m * n)
 * Space complexity: O(m * n), for the recursion stack.
 */

public class NumberOfIslands {
    private int ROWS;
    private int COLS;

    public int numIslands(char[][] grid) {
        ROWS = grid.length;
        COLS = grid[0].length;
        int numberOfIslands = 0;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (grid[r][c] == '1') {
                    numberOfIslands++;
                    dfs(grid, r, c);
                }
            }
        }
        return numberOfIslands;
    }

    private void dfs(char[][] grid, int r, int c) {
        if (r < 0 || c < 0 || r == ROWS || c == COLS || grid[r][c] == '0') {
            return;
        }

        // Mark cell as visited.
        grid[r][c] = '0';

        dfs(grid, r + 1, c);
        dfs(grid, r, c + 1);
        dfs(grid, r - 1, c);
        dfs(grid, r, c - 1);
    }
}

package leetcode.solutions.medium.graphs;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Pattern: Graphs (Multisource BFS)
 * Time complexity: O(m * n)
 * Space complexity: O(m * n)
 * Intuition: Start BFS from every initially rotten orange at once. Each BFS layer represents one minute,
 * because all oranges that are rotten at the start of that minute spread rot simultaneously to their fresh neighbors.
 * Marking a fresh orange as rotten when it is enqueued also acts as the visited check.
 */

public class RottingOranges {
    public int orangesRotting(int[][] grid) {
        Deque<int[]> queue = new ArrayDeque<>();
        int rows = grid.length;
        int cols = grid[0].length;
        int fresh = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 2) {
                    queue.add(new int[]{ r, c });
                }
                if (grid[r][c] == 1) {
                    fresh++;
                }
            }
        }

        int[][] directions = {{1, 0},{0, 1},{-1, 0},{0, -1}};
        int minutes = 0;
	    // Important: make sure that we also stop if fresh == 0
        while (fresh > 0 && !queue.isEmpty()) {
            int queueSize = queue.size();
            for (int i = 0; i < queueSize; i++) {
                int[] cell = queue.poll();
                int currentRow = cell[0];
                int currentCol = cell[1];

                for (int[] dir : directions) {
		            // Calculate next cell coordinates.
                    int newRow = currentRow + dir[0];
                    int newCol = currentCol + dir[1];

                    // If next cell is out of bound, or empty, or already rotten, skip it.
                    if (newRow < 0 || newCol < 0 || newRow == rows || newCol == cols || grid[newRow][newCol] == 0 || grid[newRow][newCol] == 2) {
                        continue;
                    }

                    // Next cell is fresh, so make it rotten and decrease the amount of fresh cells.
                    grid[newRow][newCol] = 2;
                    fresh--;
                    queue.add(new int[]{ newRow, newCol });
                }
            }
            minutes++;
        }
	    // If there are still fresh cells but the queue stopped it means that some fresh cells are unreachable, so return -1;
        return fresh > 0 ? -1 : minutes;
    }
}

package leetcode.solutions.medium.graphs;

/**
 * Pattern: Graphs (DFS)
 * Time complexity: O(m * n)
 * Space complexity: O(m * n), because of the recursive stack needed in the worst case.
 * Intuition: we identify the non-surrounded regions first, and everything else has to be surrounded.
 */

public class SurroundedRegions {
    int rows;
    int cols;
    public void solve(char[][] board) {
        rows = board.length;
        cols = board[0].length;

        // Check left and right borders.
        for (int r = 0; r < rows; r++) {
            if (board[r][0] == 'O') {
                dfs(board, r, 0);
            }
            if (board[r][cols - 1] == 'O') {
                dfs(board, r, cols - 1);
            }
        }

        // Check top and bottom borders.
        for (int c = 0; c < cols; c++) {
            if (board[0][c] == 'O') {
                dfs(board, 0, c);
            }
            if (board[rows - 1][c] == 'O') {
                dfs(board, rows - 1, c);
            }
        }

        // Explore the board one final time:
        // if we find '*', restore 'O',
        // otherwise, mark it with 'X', as the cell is surrounded.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '*') board[r][c] = 'O';
                else if (board[r][c] == 'O') board[r][c] = 'X';
            }
        }
    }

    // Explore paths with 'O' and mark them as visited with '*'.
    private void dfs(char[][] board, int r, int c) {
        if (r < 0 || c < 0 || r == rows || c == cols || board[r][c] == 'X' || board[r][c] == '*') {
            return;
        }

        board[r][c] = '*';
        dfs(board, r + 1, c);
        dfs(board, r, c + 1);
        dfs(board, r - 1, c);
        dfs(board, r, c - 1);
    }
}

package leetcode.solutions.medium.graphs;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Pattern: Graphs (Multisource BFS)
 * Time complexity: O(m * n)
 * Space complexity: O(m * n)
 */

public class ZeroOneMatrix {
    public int[][] updateMatrix(int[][] mat) {
        int ROWS = mat.length;
        int COLS = mat[0].length;
        Deque<int[]> queue = new ArrayDeque<>();

        // Mark unvisited cells as -1
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (mat[r][c] == 0) {
                    queue.add(new int[]{r, c});
                } else mat[r][c] = -1;
            }
        }

        int[][] directions = {{0,1},{1,0},{-1,0},{0,-1}};

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();

            for (int[] d : directions) {
                int nr = cell[0] + d[0];
                int nc = cell[1] + d[1];

                if (nr < 0 || nc < 0 || nr >= ROWS || nc >= COLS ||
                        mat[nr][nc] != -1) continue;

                mat[nr][nc] = mat[cell[0]][cell[1]] + 1;
                queue.add(new int[]{ nr, nc });
            }
        }
        return mat;
    }
}

package leetcode.solutions.medium.hashing;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Hashing + Two Pointers
 * Time complexity: O(n) for both encode and decode.
 * Space complexity: O(n) for both encode and decode.
 * */

public class EncodeAndDecodeStrings {
    public String encode(List<String> strs) {
        StringBuilder res = new StringBuilder();
        for (String s : strs) {
            res.append(s.length()).append('#').append(s);
        }
        return res.toString();
    }

    public List<String> decode(String str) {
        List<String> res = new ArrayList<>();
        int r = 0;
        int l;

        while (r < str.length()) {
            StringBuilder lengthAsString = new StringBuilder();

            // Find length of next string
            while (r < str.length() && (Character.isDigit(str.charAt(r)))) {
                lengthAsString.append(str.charAt(r));
                r++;
            }

            // Use length to add next string to result
            int length = Integer.parseInt(lengthAsString.toString());
            l = r + 1;
            r = l + length;
            res.add(str.substring(l, r));
        }
        return res;
    }
}

package leetcode.solutions.medium.hashing;

import java.util.*;

/**
 * Pattern: Hashing
 * Time complexity: O(n * m), where n is the number of strings and m is the length of the longest string.
 * Space complexity: O(n)
 */

public class GroupAnagrams {
    public List<List<String>> groupAnagrams(String[] strs) {
        // e.g. {[1, 0, 1, 0, 0, 0, 0, ...] : [act, cat]}
        Map<String, List<String>> patternToStringsMap = new HashMap<>();

        for (String s : strs) {
            int[] pattern = new int[26];
            for (char c : s.toCharArray()) pattern[c - 'a']++;

            // We convert to String because arrays do not implement equals() and hashCode()
            // based on their contents. Using String ensures correct key comparison.
            String patternAsString = Arrays.toString(pattern);

            // computeIfAbsent avoids doing two lookups (putIfAbsent + get)
            // and creates the list lazily, making it more efficient and idiomatic.
            patternToStringsMap
                    .computeIfAbsent(patternAsString, k -> new ArrayList<>())
                    .add(s);
        }

        return new ArrayList<>(patternToStringsMap.values());
    }
}

package leetcode.solutions.medium.hashing;

import java.util.HashSet;
import java.util.Set;

/**
 * Pattern: Hashing
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class LongestConsecutiveSequence {
    public int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();

        for (int num : nums) set.add(num);

        int maxLength = 0;
        for (int num: nums) {
            if (set.contains(num - 1)) continue;
            else {
                int length = 1, curNum = num + 1;
                while (set.contains(curNum)) {
                    curNum++;
                    length++;
                }
                maxLength = Math.max(maxLength, length);
            }
        }
        return maxLength;
    }
}

package leetcode.solutions.medium.hashing;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pattern: Hashing, Bucket Sort (note: bucket sort ensures sorting because it is a list).
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class TopKFrequentElements {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>(); // element -> frequency
        List<Integer>[] frequencies = new ArrayList[nums.length + 1]; // Be mindful of off-by-one here.

        // Fill frequencies with empty buckets.
        for (int i = 0; i < frequencies.length; i++) {
            frequencies[i] = new ArrayList<>();
        }

        // Calculate frequencies.
        for (int n : nums) count.put(n, count.getOrDefault(n, 0) + 1);

        // Add values to buckets based on frequencies.
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            frequencies[entry.getValue()].add(entry.getKey());
        }

        int[] res = new int[k];
        int index = 0;
        for (int i = frequencies.length - 1; i > 0; i--) {
            for (int n : frequencies[i]) {
                res[index++] = n;
                if (index == k) return res;
            }
        }
        return res;
    }
}

package leetcode.solutions.medium.hashing;

import java.util.*;

/**
 * Pattern: Hashing
 * Time complexity: O(n^2) - Structurally O(n^2) as it traverses every cell, but technically O(1) since the board is always 9x9.
 * Space complexity: O(n^2) - O(1) since board is 9x9
 * */

public class ValidSudoku {
    public boolean isValidSudoku(char[][] board) {
        Map<Integer, Set<Character>> rows = new HashMap<>();
        Map<Integer, Set<Character>> cols = new HashMap<>();
        Map<String, Set<Character>> squares = new HashMap<>();

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') continue;
                String squareKey = (r / 3) + "," + (c / 3);

                if (rows.computeIfAbsent(r, k -> new HashSet<>()).contains(board[r][c]) ||
                        cols.computeIfAbsent(c, k -> new HashSet<>()).contains(board[r][c]) ||
                        squares.computeIfAbsent(squareKey, k -> new HashSet<>()).contains(board[r][c])) {
                    return false;
                }

                rows.get(r).add(board[r][c]);
                cols.get(c).add(board[r][c]);
                squares.get(squareKey).add(board[r][c]);
            }
        }
        return true;
    }
}

package leetcode.solutions.medium.heaps;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;

/**
 * Pattern: min-heap
 * Time complexity: postTweet(), follow() and unfollow() take O(1) time, getNewsFeed() takes O(f * log f). 
 * where f is the number of followers, for the frontier build-up.
 * 
 * Space complexity: O(N * m + N * M + n) where n is the total number of followers associated with userId,
 * m is the maximum number of tweets per user, N is the total number of user ids and M is the maximum number of 
 * followers per user.
 */
class Twitter {
    private Map<Integer, List<int[]>> tweetsMap; // tweet: [tweetId, creationTime]
    private Map<Integer, Set<Integer>> followersMap;
    private int time;

    public Twitter() {
        this.tweetsMap = new HashMap<>();
        this.followersMap = new HashMap<>();
        this.time = 0;
    }

    public void postTweet(int userId, int tweetId) {
        int[] tweet = new int[] { tweetId, time };
        tweetsMap
            .computeIfAbsent(userId, k -> new ArrayList<>())
            .add(tweet);
        time++;
    }

    public List<Integer> getNewsFeed(int userId) {
        PriorityQueue<int[]> minHeap = new PriorityQueue<>(
            (a, b) -> b[1] - a[1]
        );

        // Make a copy, otherwise followers.add(userId) mutates the real map list.
        Set<Integer> followers = new HashSet<>(
            followersMap.getOrDefault(userId, new HashSet<>())
        );

        // User should see their own tweets too.
        followers.add(userId);

        // Build frontier (most recent tweets in each list of tweets) and push them to the min-heap.
        for (int follower : followers) {
            List<int[]> tweets = tweetsMap.get(follower);

            if (tweets == null) continue;

            int index = tweets.size() - 1;
            int[] tweet = tweets.get(index);
            minHeap.offer(new int[] { tweet[0], tweet[1], follower, index - 1 });
        }

        List<Integer> topTenTweets = new ArrayList<>();
        while (!minHeap.isEmpty() && topTenTweets.size() < 10) {
            // Take the most recent tweet and add to solution.
            int[] topTweet = minHeap.poll();
            topTenTweets.add(topTweet[0]);

            // Move index to the next most recent tweet in the same list and add it to minHeap.
            // It could still be more recent than other tweets in the frontier and we do not want to miss it.
            int topTweetIndex = topTweet[3];
            if (topTweetIndex >= 0) {
                int[] newTweet = tweetsMap.get(topTweet[2]).get(topTweet[3]);
                minHeap.offer(new int[] { newTweet[0], newTweet[1], topTweet[2], topTweetIndex - 1 });
            }
        }

        return topTenTweets;
    }

    public void follow(int followerId, int followeeId) {
        followersMap.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> followees = followersMap.get(followerId);
        if (followees == null) return;
        followees.remove(followeeId);
    }
}

package leetcode.solutions.medium.heaps;

import java.util.PriorityQueue;

/**
 * Pattern: max-heap
 * Time complexity: O(n * log k)
 * Space complexity: O(k)
 */

class Solution {
    public int[][] kClosest(int[][] points, int k) {
        PriorityQueue<int[]> maxHeap = new PriorityQueue<>(
            (a, b) -> Integer.compare(b[0] * b[0] + b[1] * b[1],
                                      a[0] * a[0] + a[1] * a[1]));

        for (int[] point : points) {
            maxHeap.offer(point);
            if (maxHeap.size() > k) maxHeap.poll();
        }

        int[][] res = new int[k][2];
        int i = 0;
        while (!maxHeap.isEmpty()) {
            int[] point = maxHeap.poll();
            res[i++] = point;
        }
        return res;
    }
}

package leetcode.solutions.medium.heaps;

import java.util.PriorityQueue;

/**
 * Pattern: min-heap
 * Time complexity: O(n * log k)
 * Space complexity: O(k)
 */

public class KthLargestElementInAnArray {
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();

        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k)
                minHeap.poll();
        }
        return minHeap.peek();
    }
}

package leetcode.solutions.medium.intervals;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Intervals (Greedy)
 * Time complexity: O(n)
 * Space complexity: O(n)

 * Called greedy because at each step we make a locally optimal, irrevocable decision
 * about the current interval without backtracking:
 *   1. Add it as-is     — it ends before the new interval starts, so no overlap is possible.
 *   2. Flush then add   — it starts after the new interval ends, so the merge window is closed.
 *   3. Merge            — it overlaps, so we expand the new interval's bounds on the spot.

 * This works because the input is already sorted: once an interval is non-overlapping
 * to the left, no future interval can change that, so we never need to revisit a decision.
 */

public class InsertInterval {
        public int[][] insert(int[][] intervals, int[] newInterval) {
            // Using int[] instead of List<Integer> makes it easier to convert data structures later.
            List<int[]> res = new ArrayList<>();
            for (int[] interval : intervals) {
                if (newInterval == null || interval[1] < newInterval[0]) {
                    res.add(interval);
                } else if (interval[0] > newInterval[1]) {
                    res.add(newInterval);
                    res.add(interval);
                    newInterval = null;
                } else {
                    newInterval[0] = Math.min(interval[0], newInterval[0]);
                    newInterval[1] = Math.max(interval[1], newInterval[1]);
                }
            }
            // This case is useful for, e.g., the following edge case:
            // intervals = [], newInterval not null.
            if (newInterval != null) res.add(newInterval);

            // This conversion is needed to satisfy the return type int[][] requirement.
            // .toArray() converts res into int[][] by specifying the overall length
            // and then copying each int[] array into it.
            return res.toArray(new int[res.size()][]);
        }
}

package leetcode.solutions.medium.intervals;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Pattern: Intervals (Greedy)
 * Time complexity: O(n * log n)
 * Space complexity: O(n)
 */

public class MergeIntervals {
    public int[][] merge(int[][] intervals) {
        // Remember: (a[0] - b[0]) <= 0, so a <= b, so a comes before b in the ordering.
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        int[] mergedInterval = intervals[0];
        List<int[]> res = new ArrayList<>();

        for (int i = 0; i < intervals.length - 1; i++) {
            if (mergedInterval[1] < intervals[i + 1][0]) {
                res.add(mergedInterval);
                mergedInterval = intervals[i + 1];
            } else {
                mergedInterval[1] = Math.max(mergedInterval[1], intervals[i + 1][1]);
            }
        }
        res.add(mergedInterval);
        return res.toArray(new int[res.size()][]);
    }
}

package leetcode.solutions.medium.intervals;

import java.util.Arrays;

/**
 * Pattern: Intervals (Greedy)
 * Time complexity: O(n * log n)
 * Space complexity: O(n)
 */

public class NonOverlappingIntervals {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        int lastEnd = intervals[0][1];
        int res = 0;

        for (int i = 0; i < intervals.length - 1; i++) {
            if (intervals[i + 1][0] < lastEnd) {
                res++;
                lastEnd = Math.min(lastEnd, intervals[i + 1][1]);
            } else {
                // We did not remove an interval, so we make sure to update lastEnd with the latest interval end.
                // lastEnd = intervals[i + 1][1] would also work, but we prefer a more explicit version.
                lastEnd = Math.max(lastEnd, intervals[i + 1][1]);
            }
        }
        return res;
    }
}

package leetcode.solutions.medium.linkedlist;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List (Math)
 * Time complexity: O(m + n) where m and n are the lengths of the two linked lists.
 * Space complexity: O(max(m, n)) for the output list;
 */

public class AddTwoNumbers {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode curr = new ListNode(0);
        ListNode dummy = curr;

        int carry = 0;
        while (l1 != null || l2 != null) {
            // It could be that one list/number is longer than the other.
            // We make sure we have a default value.
            int val1 = l1 != null ? l1.val : 0;
            int val2 = l2 != null ? l2.val : 0;
            int val3 = val1 + val2 + carry;

            // Should we carry something ahead?
            carry = val3 > 9 ? 1 : 0;

            curr.next = new ListNode(val3 % 10);
            curr = curr.next;
            l1 = (l1 != null) ? l1.next : null;
            l2 = (l2 != null) ? l2.next : null;
        }

        // Remember to check if there is one last carry to add.
        curr.next = carry > 0 ? new ListNode(1) : null;
        return dummy.next;
    }
}

package leetcode.solutions.medium.linkedlist;

import leetcode.solutions.types.ListNodeWithRandomPointer;
import java.util.HashMap;
import java.util.Map;

public class CopyLinkedListWithRandomPointer {
    public ListNodeWithRandomPointer copyRandomList(ListNodeWithRandomPointer head) {
        Map<ListNodeWithRandomPointer, ListNodeWithRandomPointer> originalToCopy = new HashMap<>();

        // Store clones of nodes in HashMap without any links.
        ListNodeWithRandomPointer curr = head;
        while (curr != null) {
            ListNodeWithRandomPointer copy = new ListNodeWithRandomPointer(curr.val);
            originalToCopy.put(curr, copy);
            curr = curr.next;
        }

        // Create links in new linked list based on old linked list.
        curr = head;
        while (curr != null) {
            originalToCopy.get(curr).next = originalToCopy.getOrDefault(curr.next, null);
            originalToCopy.get(curr).random = originalToCopy.getOrDefault(curr.random, null);
            curr = curr.next;
        }
        return originalToCopy.get(head);
    }
}

package leetcode.solutions.medium.linkedlist;

import leetcode.solutions.types.DoublyLinkedListNode;
import java.util.HashMap;
import java.util.Map;

/**
 * Pattern: Doubly Linked List
 * Time complexity: O(1) for get and put operations
 * Space complexity: O(n)
 * Intuition: Use a doubly linked list to maintain the order of usage and 
 * a hash map to store the key and corresponding node for O(1) access.
 */

class LRUCache {
    int capacity;
    int size = 0;
    // Map to store the key and corresponding node in the doubly linked list.
    Map<Integer, DoublyLinkedListNode> map = new HashMap<>();
    DoublyLinkedListNode left;  // LRU
    DoublyLinkedListNode right; // MRU

    public LRUCache(int capacity) {
        this.capacity = capacity;
        left = new DoublyLinkedListNode(0, 0);
        right = new DoublyLinkedListNode(0, 0);
        left.next = right;
        right.prev = left;
    }

    // Remove the node from the list.
    private void removeNode(DoublyLinkedListNode node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    // Append the node to the right (MRU) end of the list.
    private void appendRight(DoublyLinkedListNode node) {
        DoublyLinkedListNode prev = right.prev;
        prev.next = node;
        node.prev = prev;
        node.next = right;
        right.prev = node;
    }

    // Get the value of the key if it exists, otherwise return -1.
    public int get(int key) {
        if (!map.containsKey(key)) return -1;

        DoublyLinkedListNode node = map.get(key);
        removeNode(node);
        appendRight(node);

        return node.value;
    }

    // Update the value of the key if it exists, otherwise add the key-value pair to the cache
    // If the cache exceeds its capacity, remove the least recently used key.
    public void put(int key, int value) {
        if (map.containsKey(key)) {
            DoublyLinkedListNode node = map.get(key);
            node.value = value;
            removeNode(node);
            appendRight(node);
            return;
        }

        DoublyLinkedListNode node = new DoublyLinkedListNode(key, value);
        map.put(key, node);
        appendRight(node);
        size++;

        if (size > capacity) {
            DoublyLinkedListNode lru = left.next;
            removeNode(lru);
            map.remove(lru.key);
            size--;
        }
    }
}

package leetcode.solutions.medium.linkedlist;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List (Two Pointers)
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class RemoveNodeFromEndOfLinkedList {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0, head);
        ListNode first = head;
        ListNode second = dummy;

        // Move first pointer n nodes to the right to create a gap of n nodes
        // between first and second pointer.
        while (n > 0) {
            first = first.next;
            n--;
        }

        // Advance first and second pointers together with the same pace.
        // Since first was *before* head at the beginning, it will end up right *before* the node to be removed.
        while (first != null) {
            first = first.next;
            second = second.next;
        }

        // Remove node.
        second.next = second.next.next;
        return dummy.next;
    }
}

package leetcode.solutions.medium.linkedlist;

import leetcode.solutions.types.ListNode;

/**
 * Pattern: Linked List
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class ReorderLinkedList {
    public void reorderList(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;

        // 1. Find the middle point.
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode secondHalf = slow.next;
        // break the middle link
        slow.next = null;

        // 2. Reverse the second half.
        slow = null;
        while (secondHalf != null) {
            ListNode tmp = secondHalf.next;
            secondHalf.next = slow;
            slow = secondHalf;
            secondHalf = tmp;
        }

        ListNode firstHalf = head;
        secondHalf = slow;

        // 3. Merge first and reverse second half together, alternating nodes.
        while (secondHalf != null) {
            ListNode tmp1 = firstHalf.next;
            ListNode tmp2 = secondHalf.next;
            firstHalf.next = secondHalf;
            secondHalf.next = tmp1;
            firstHalf = tmp1;
            secondHalf = tmp2;
        }
    }
}

package leetcode.solutions.medium.slidingwindow;

import java.util.HashMap;
import java.util.Map;

/**
 * Pattern: Sliding Window
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class LongestRepeatingCharacterReplacement {
    public int characterReplacement(String s, int k) {
        Map<Character, Integer> count = new HashMap<>();
        int l = 0, maxFrequency = 0, maxLength = 0;

        for (int r = 0; r < s.length(); r++) {
            // Update the count of the current character and the maximum frequency in the current window
            count.put(s.charAt(r), 1 + count.getOrDefault(s.charAt(r), 0));
            maxFrequency = Math.max(maxFrequency, count.get(s.charAt(r)));

            // If the current window size minus the count of the most frequent character is greater than k,
            // it means we need to shrink the window from the left
            while (((r - l + 1) - maxFrequency) > k) {
                count.put(s.charAt(l), count.get(s.charAt(l)) - 1);
                l++;
            }
            maxLength = Math.max(maxLength, (r - l + 1));
        }
        return maxLength;
    }
}

package leetcode.solutions.medium.slidingwindow;

import java.util.HashSet;
import java.util.Set;

/**
 * Pattern: Sliding Window
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class LongestSubstringWithoutRepeatingCharacters {
    public int lengthOfLongestSubstring(String s) {
        Set<Character> charSet = new HashSet<>();
        int l = 0;
        int maxSubstringLength = 0;

        for (int r = 0; r < s.length(); r++) {
            while (charSet.contains(s.charAt(r))) {
                charSet.remove(s.charAt(l));
                l++;
            }
            charSet.add(s.charAt(r));
            maxSubstringLength = Math.max(maxSubstringLength, r - l + 1);
        }
        return maxSubstringLength;
    }
}

package leetcode.solutions.medium.slidingwindow;

import java.util.Arrays;

/**
 * Pattern: Sliding Window
 * Time complexity: O(n)
 * Space complexity: O(n)
 * Note: we might be tempted to use a HashSet to check for the presence of characters, 
 * but since we need to check for the frequency of characters, using an array to count the frequency is more efficient
 * and less error-prone than using a HashMap or HashSet.
 */

public class PermutationInString {
    public boolean checkInclusion(String s1, String s2) {
        if (s1.length() > s2.length()) return false;

        int[] need = new int[26];
        int[] window = new int[26];

        // Count the frequency of characters in s1.
        for (char c : s1.toCharArray()) {
            need[c - 'a']++;
        }

        int left = 0;
        for (int right = 0; right < s2.length(); right++) {
            window[s2.charAt(right) - 'a']++;

            // If the window size exceeds the length of s1, shrink the window from the left.
            if (right - left + 1 > s1.length()) {
                window[s2.charAt(left) - 'a']--;
                left++;
            }

            // Check if the current window matches the frequency of characters needed.
            if (Arrays.equals(need, window)) {
                return true;
            }
        }
        return false;
    }
}

package leetcode.solutions.medium.sorting;

import java.util.Arrays;

/**
 * Pattern: Sorting
 * Time complexity: O(n log n)
 * Space complexity: O(log n) - due to sorting stack
 * */

public class HIndex {
    public int hIndex(int[] citations) {
        // 1. Sort the citations (e.g., [3, 0, 6, 1, 5] -> [0, 1, 3, 5, 6])
        Arrays.sort(citations);
        int n = citations.length;

        // 2. Iterate to find the point where citations >= remaining papers
        for (int i = 0; i < n; i++) {
            int hCandidate = n - i; // Number of papers with at least citations[i] citations
            if (citations[i] >= hCandidate) {
                return hCandidate;
            }
        }

        return 0;
    }
}

package leetcode.solutions.medium.sorting;

/**
 * Pattern: Counting Sort
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class SortColors {
    public void sortColors(int[] nums) {
        int[] frequencies = new int[3];

        for (int num : nums) frequencies[num]++;

        for (int i = 0; i < nums.length; i++) {
            if (frequencies[0] > 0) {
                nums[i] = 0;
                frequencies[0]--;
            } else if (frequencies[1] > 0) {
                nums[i] = 1;
                frequencies[1]--;
            } else {
                nums[i] = 2;
                frequencies[2]--;
            }
        }
    }
}

package leetcode.solutions.medium.stack;

import java.util.Arrays;
import java.util.Stack;

/**
 * Pattern: Stack
 * Time complexity: O(n log n) because of sorting
 * Space complexity: O(n)
 */

public class CarFleet {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        int[][] pairs = new int[n][2];

        for (int i = 0; i < n; i++) {
            pairs[i][0] = position[i];
            pairs[i][1] = speed[i];
        }

        // Sort by position descending (closest to target first).
        // A car can only catch up on another car that is further ahead, not behind it.
        Arrays.sort(pairs, (a, b) -> Integer.compare(b[0], a[0]));
        Stack<Double> stack = new Stack<>();

        for (int[] pair : pairs) {
            double timeToArrive = (double)(target - pair[0]) / pair[1];

            // Only push if this car forms a new fleet (or the stack is empty of course)
            // i.e., it cannot catch up to the fleet ahead
            if (stack.isEmpty() || timeToArrive > stack.peek()) {
                stack.push(timeToArrive);
            }
        }
        return stack.size();
    }
}

package leetcode.solutions.medium.stack;

import java.util.Stack;

/**
 * Pattern: Stack
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class DailyTemperatures {
    public int[] dailyTemperatures(int[] temperatures) {
        int[] res = new int[temperatures.length];
        Stack<int[]> stack = new Stack<>(); // pair: [temp, index]

        for (int i = 0; i < temperatures.length; i++) {
            int temp = temperatures[i];
            while (!stack.isEmpty() && temp > stack.peek()[0]) {
                int[] pair = stack.pop();
                res[pair[1]] = i - pair[1];
            }
            stack.push(new int[] { temp, i });
        }
        return res;
    }
}

package leetcode.solutions.medium.stack;

import java.util.Stack;

/**
 * Pattern: Stack
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class EvaluateReversePolishNotation {
    public int evalRPN(String[] tokens) {
        Stack<Integer> stack = new Stack<>();

        for (String t : tokens) {
            switch (t) {
                case "+" -> stack.push(stack.pop() + stack.pop());
                case "-" -> {
                    int num1 = stack.pop();
                    int num2 = stack.pop();
                    stack.push(num2 - num1);
                }
                case "*" -> stack.push(stack.pop() * stack.pop());
                case "/" -> {
                    int num1 = stack.pop();
                    int num2 = stack.pop();
                    stack.push(num2 / num1); // Integer division required here by statement.
                }
                default -> stack.push(Integer.parseInt(t));
            }
        }
        return stack.pop();
    }
}

package leetcode.solutions.medium.stack;

import java.util.Stack;

/**
 * Pattern: Stack
 * Time complexity: O(1) for all operations
 * Space complexity: O(n)
 */

public class MinStack {
    Stack<Integer> minStack;
    Stack<Integer> normalStack;

    public MinStack() {
        minStack = new Stack<>();
        normalStack = new Stack<>();
    }

    public void push(int val) {
        normalStack.push(val);

        // Do not forget to use <=
        if (minStack.isEmpty() || val <= minStack.peek()) {
            minStack.push(val);
        }
    }

    public void pop() {
        int poppedElement = normalStack.pop();
        if (poppedElement == minStack.peek()) {
            minStack.pop();
        }
    }

    public int top() {
        return normalStack.peek();
    }

    public int getMin() {
        return minStack.peek();
    }
}

package leetcode.solutions.medium.tree;

import leetcode.solutions.types.TreeNode;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * Pattern: Trees (BFS)
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class BinaryTreeLevelOrderTraversal {
    public List<List<Integer>> levelOrder(TreeNode root) {
        Deque<TreeNode> queue = new ArrayDeque<>();
        List<List<Integer>> res = new ArrayList<>();

        if (root != null) queue.add(root);

        while (!queue.isEmpty()) {
            List<Integer> level = new ArrayList<>();
            // Remember to extract queue size *before* getting into the loop!
            int queueSize = queue.size();
            for (int i = 0; i < queueSize; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);

                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }
            res.add(level);
        }
        return res;
    }
}

package leetcode.solutions.medium.tree;

