package leetcode.solutions.medium.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Trees (DFS)
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class CountGoodNodesInBinaryTree {
    public int goodNodes(TreeNode root) {
        return dfs(root, root.val);
    }

    private int dfs(TreeNode root, int maxSoFar) {
        if (root == null) return 0;

        int toAdd = maxSoFar <= root.val ? 1 : 0;
        maxSoFar = Math.max(maxSoFar, root.val);
        return toAdd + dfs(root.left, maxSoFar) + dfs(root.right, maxSoFar);
    }
}

package leetcode.solutions.medium.tree;

import leetcode.solutions.types.TreeNode;

import java.util.ArrayList;
import java.util.List;

/**
 * Pattern: Trees (DFS)
 * Time complexity: O(n)
 * Space complexity: O(n)
 * Note: inorder traversal in a binary search tree yields values in increasing order.
 */

public class KthSmallestIntegerInBST {
    public int kthSmallest(TreeNode root, int k) {
        List<Integer> list = new ArrayList<>();

        dfs(root, list);
        // k is 1-indexed.
        return list.get(k - 1);
    }

    private void dfs(TreeNode root, List<Integer> list) {
        if (root == null) return;

        dfs(root.left, list);
        list.add(root.val);
        dfs(root.right, list);
    }
}

package leetcode.solutions.medium.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: binary search trees
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class LowestCommonAncestorInBinarySearchTree {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        // If this is the case, p is on the left and q is on the right, or the other way around,
        // therefore root has to be the lowest common ancestor.
        if ((p.val < root.val && q.val > root.val) || (q.val < root.val && p.val > root.val)) {
            return root;
        }
        // Remember that p and q are not within the tree, so we cannot compare memory locations, but only values.
        if (p.val == root.val || q.val == root.val) return root;

        if (p.val < root.val) return lowestCommonAncestor(root.left, p, q);
        return lowestCommonAncestor(root.right, p, q);
    }
}

package leetcode.solutions.medium.tree;

import leetcode.solutions.types.TreeNode;

/**
 * Pattern: Trees (DFS)
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class ValidateBinarySearchTree {
    public boolean isValidBST(TreeNode root) {
        int[] res = dfs(root);
        return res[2] == 1;
    }

    /** Returns [ minRight, maxLeft, isValid ] */
    private int[] dfs(TreeNode root) {
        if (root == null) return new int[]{ Integer.MAX_VALUE, Integer.MIN_VALUE, 1 };

        int[] left = dfs(root.left);
        int[] right = dfs(root.right);

        // if left/right subtree invalid → propagate invalidity.
        if (left[2] == 0 || right[2] == 0) return new int[]{ 0, 0, 0 };

        // BST property check. If invalid → propagate invalidity.
        if (!(left[1] < root.val && root.val < right[0])) {
            return new int[]{ 0, 0, 0 };
        }

        // When calculating, say, min, we do not need to compare left[0], right[0] and root because
        // we already know that right[0] is bigger than root, otherwise we would have returned already above.
        // Same holds, respectively, for max.
        int min = Math.min(left[0], root.val);
        int max = Math.max(right[1], root.val);

        return new int[]{ min, max, 1 };
    }
}

package leetcode.solutions.medium.tries;

import leetcode.solutions.types.TrieNode;

/**
 * Pattern: Tries (DFS)
 * Time complexity: O(n) for both methods, where n is the length of word.
 * The reason this is the case despite the wildcard is that there is a constraint in this problem:
 * - there will be at most two dots in word. This means that, in the worst case when the two dots are
 * one after the other, we will have 26² = 676 checks, so the result is O(676 * n) = O(n). If it was not
 * for this constraint, the time complexity would be O(26ⁿ), exponential.

 * Space complexity: O(n), because we create one TrieNode per character in word.
 */

public class DesignAddAndSearchWordDataStructure {
    TrieNode root;

    public DesignAddAndSearchWordDataStructure() {
        root = new TrieNode();
    }

    public void addWord(String word) {
        TrieNode curr = this.root;
        for (char c : word.toCharArray()) {
            curr.children.putIfAbsent(c, new TrieNode());
            curr = curr.children.get(c);
        }
        curr.isEndOfWord = true;
    }

    public boolean search(String word) {
        return dfs(word, 0, this.root);
    }

    private boolean dfs(String word, int i, TrieNode curr) {
        if (i == word.length()) return curr.isEndOfWord;

        char currentChar = word.charAt(i);

        if (currentChar != '.') {
            TrieNode next = curr.children.get(currentChar);
            // Check if character was inserted before in the Trie.
            if (next == null) return false;
            return dfs(word, i + 1, next);
        }

        // currentChar == '.', the wildcard.
        for (TrieNode child : curr.children.values()) {
            // Important! At least one path needs to be good to return true.
            if (dfs(word, i + 1, child)) {
                return true;
            }
        }
        return false;
    }
}

package leetcode.solutions.medium.tries;

import leetcode.solutions.types.TrieNode;

/**
 * Pattern: Trie
 * Time complexity: O(n), for all function calls, where n is the length of word.
 * Space complexity: O(n), because we create one TrieNode per character in word.
 */

public class ImplementTrie {
    private final TrieNode root;

    public ImplementTrie() {
        this.root = new TrieNode();
    }

    public void insert(String word) {
        TrieNode curr = this.root;

        for (char c : word.toCharArray()) {
            curr.children.putIfAbsent(c, new TrieNode());
            curr = curr.children.get(c);
        }
        curr.isEndOfWord = true;
    }

    public boolean search(String word) {
        TrieNode curr = this.root;

        for (char c : word.toCharArray()) {
            if (curr.children.containsKey(c)) {
                curr = curr.children.get(c);
            } else return false;
        }
        return curr.isEndOfWord;
    }

    public boolean startsWith(String prefix) {
        TrieNode curr = this.root;

        for (char c : prefix.toCharArray()) {
            if (curr.children.containsKey(c)) {
                curr = curr.children.get(c);
            } else return false;
        }
        return true;
    }
}

package leetcode.solutions.medium.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class ContainerWithMostWater {
    public int maxArea(int[] heights) {
        int maxSize = 0;

        int l = 0, r = heights.length - 1;
        while (l < r) {
            int size = Math.min(heights[l], heights[r]) * (r - l);
            maxSize = Math.max(maxSize, size);

            if (heights[l] < heights[r]) {
                l++;
            } else {
                r--;
            }
        }
        return maxSize;
    }
}

package leetcode.solutions.medium.twopointers;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Pattern: Two Pointers + Sorting
 * Time complexity: O(n^2), because of the combination of outer for and inner while loops.
 * Space complexity: O(log n) for the sorting algorithm.
 */

public class ThreeSum {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> res = new ArrayList<>();

        // do NOT start from i = 1 as we would miss this case: [0, 0, 0].
        // Start from i = 0 and check if i > 0 below.
        for (int i = 0; i < nums.length; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;

            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int sum = nums[i] + nums[l] + nums[r];
                if (sum > 0) {
                    r--;
                } else if (sum < 0) {
                    l++;
                } else {
                    res.add(Arrays.asList(nums[i], nums[l], nums[r]));
                    l++;
                    r--;
                    while (l < r && nums[l] == nums[l - 1]) {
                        l++;
                    }
                }
            }
        }
        return res;
    }
}

package leetcode.solutions.medium.twopointers;

/**
 * Pattern: Two Pointers
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class TwoSumII {
    public int[] twoSum(int[] numbers, int target) {
        int l = 0, r = numbers.length - 1;

        while (l < r) {
            int sum = numbers[l] + numbers[r];

            if (sum > target) {
                r--;
            } else if (sum < target) {
                l++;
            } else {
                return new int[] {l + 1, r + 1};
            }
        }
        return new int[] {};
    }
}

package leetcode.solutions.medium.various;

/**
 * Pattern: Negative Marking
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

public class FindTheDuplicateNumber {
    public int findDuplicate(int[] nums) {
        for (int num : nums) {
            int index = Math.abs(num) - 1; // Absolute value is needed as `num` could be a value we negated.
            if (nums[index] < 0) {
                return Math.abs(num); // We return the number that would send us to a negated value, so a place we already visited.
            }
            nums[index] *= -1;
        }
        return -1;
    }
}

package leetcode.solutions.medium.various;

/**
 * Pattern: Prefix & Suffix
 * Time complexity: O(n)
 * Space complexity: O(n)
 */

public class ProductsOfArraysExceptSelf {
    public int[] productExceptSelf(int[] nums) {
        int[] res = new int[nums.length];
        int prefix = 1;

        for (int i = 0; i < nums.length; i++) {
            res[i] = prefix;
            prefix *= nums[i];
        }

        int postfix = 1;
        for (int i = nums.length - 1; i >= 0; i--) {
            res[i] *= postfix;
            postfix *= nums[i];
        }
        return res;
    }
}
